RiffleLowerV2.Thinning.Compat.FiniteLaw..type:
∀ {Ω : Type u_1} {inst : Fintype Ω} {mass : Ω → ℝ} {mass_nonneg : ∀ (ω : Ω), 0 ≤ mass ω}
  {mass_sum : ∑ ω : Ω, mass ω = 1} {mass_1 : Ω → ℝ} {mass_nonneg_1 : ∀ (ω : Ω), 0 ≤ mass_1 ω}
  {mass_sum_1 : ∑ ω : Ω, mass_1 ω = 1},
  { mass := mass, mass_nonneg := mass_nonneg, mass_sum := mass_sum } =
      { mass := mass_1, mass_nonneg := mass_nonneg_1, mass_sum := mass_sum_1 } →
    mass = mass_1

RiffleLowerV2.integerBoundary.eq_1.type:
∀ (H : Finset ℤ),
  RiffleLowerV2.integerBoundary H =
    {z ∈ H ∪ Finset.image (fun (z : ℤ) => z - 1) H | z ∈ H ∧ z + 1 ∉ H ∨ z ∉ H ∧ z + 1 ∈ H}

RiffleLowerV2.Ascent.badLeftBoundaries.e.type:
∀ {N : ℕ} (G : RiffleLowerV2.PathEdges N) (H : Finset (Fin N)),
  RiffleLowerV2.Ascent.badLeftBoundaries G H =
    {e ∈ RiffleLowerV2.Ascent.retainedBoundaries G H | ¬RiffleLowerV2.Ascent.leftComponent G e ⊆ H}

TimeProfile.TimeMesh.cell.eq_1.type:
∀ {T : ℝ} (mesh : TimeProfile.TimeMesh T) (q : Fin mesh.cellCount),
  mesh.cell q =
    if ↑q + 1 = mesh.cellCount then Set.Icc (mesh.boundary q.castSucc) (mesh.boundary q.succ)
    else Set.Ico (mesh.boundary q.castSucc) (mesh.boundary q.succ)

RiffleLowerV2.Types.cellPositionCount_eq.type:
∀ {k N K : ℕ} (cuts : TimeProfile.Cuts k N K) (hN : 0 < N) (P : TimeProfile.BorelPartition k) (I : Finset (Fin K))
  (i : Fin P.cellCount),
  RiffleLowerV2.cellPositionCount cuts hN P I i = Fintype.card { j : ↥I // P.classify (cuts.profile hN ↑j) = i }

RiffleLowerV2.Types.wordCellCount_eq_fib.type:
∀ {k N K : ℕ} (cuts : TimeProfile.Cuts k N K) (hN : 0 < N) (P : TimeProfile.BorelPartition k) {I : Finset (Fin K)}
  (x : RiffleLowerV2.WordOn k I) (i : Fin P.cellCount) (l : Fin k),
  RiffleLowerV2.wordCellCount cuts hN P x i l = Fintype.card { j : ↥I // P.classify (cuts.profile hN ↑j) = i ∧ x j = l }

RiffleLowerV2.Ascent.boundary_right_inde.type:
∀ {N : ℕ} (G : RiffleLowerV2.PathEdges N),
  Set.InjOn (fun (e : Fin (N - 1)) => RiffleLowerV2.componentIndex G (RiffleLowerV2.edgeRight e))
    {e : Fin (N - 1) | e ∉ G}

RiffleShuffle.PileProfile.mk.inj.type:
∀ {N k K : ℕ} {count : Fin K → Fin k → ℕ} {deck_pos : 0 < N} {alphabet_two : 2 ≤ k}
  {total : ∀ (j : Fin K), ∑ a : Fin k, count j a = N} {count_1 : Fin K → Fin k → ℕ} {deck_pos_1 : 0 < N}
  {alphabet_two_1 : 2 ≤ k} {total_1 : ∀ (j : Fin K), ∑ a : Fin k, count_1 j a = N},
  { count := count, deck_pos := deck_pos, alphabet_two := alphabet_two, total := total } =
      { count := count_1, deck_pos := deck_pos_1, alphabet_two := alphabet_two_1, total := total_1 } →
    count = count_1

RiffleLowerV2.ColdGeometryData.mk.inj.type:
∀ {k K : ℕ} {P : TimeProfile.BorelPartition k} {W : RiffleLowerV2.ColdWitnessData} {ambient : RiffleLowerV2.Word k K}
  {prefixType tailType : RiffleLowerV2.RoundedTypeData P}
  {central reserveMinus reservePlus : RiffleLowerV2.WordOn k (RiffleLowerV2.bridgeColumns K W)}
  {leftGood rightGood : Fin K} {ambient_1 : RiffleLowerV2.Word k K}
  {prefixType_1 tailType_1 : RiffleLowerV2.RoundedTypeData P}
  {central_1 reserveMinus_1 reservePlus_1 : RiffleLowerV2.WordOn k (RiffleLowerV2.bridgeColumns K W)}
  {leftGood_1 rightGood_1 : Fin K},
  { ambient := ambient, prefixType := prefixType, tailType := tailType, central := central,
        reserveMinus := reserveMinus, reservePlus := reservePlus, leftGood := leftGood, rightGood := rightGood } =
      { ambient := ambient_1, prefixType := prefixType_1, tailType := tailType_1, central := central_1,
        reserveMinus := reserveMinus_1, reservePlus := reservePlus_1, leftGood := leftGood_1,
        rightGood := rightGood_1 } →
    ambient = ambient_1 ∧
      prefixType = prefixType_1 ∧
        tailType = tailType_1 ∧
          central = central_1 ∧
            reserveMinus = reserveMinus_1 ∧
              reservePlus = reservePlus_1 ∧ leftGood = leftGood_1 ∧ rightGood = rightGood_1

RiffleShuffle.ShuffleMatrix.mk.inj.type:
∀ {N k K : ℕ} {P : RiffleShuffle.PileProfile N k K} {rows : Fin N → RiffleShuffle.Word k K}
  {column_count : ∀ (j : Fin K) (a : Fin k), {i : Fin N | List.Vector.get (rows i) j = a}.card = P.count j a}
  {rows_1 : Fin N → RiffleShuffle.Word k K}
  {column_count_1 : ∀ (j : Fin K) (a : Fin k), {i : Fin N | List.Vector.get (rows_1 i) j = a}.card = P.count j a},
  { rows := rows, column_count := column_count } = { rows := rows_1, column_count := column_count_1 } → rows = rows_1

TimeProfile.TimeMesh.mk.inj.type:
∀ {T : ℝ} {cellCount : ℕ} {cellCount_pos : 0 < cellCount} {boundary : Fin (cellCount + 1) → ℝ}
  {strictMono_boundary : StrictMono boundary} {boundary_zero : boundary 0 = 0}
  {boundary_last : boundary (Fin.last cellCount) = T} {cellCount_1 : ℕ} {cellCount_pos_1 : 0 < cellCount_1}
  {boundary_1 : Fin (cellCount_1 + 1) → ℝ} {strictMono_boundary_1 : StrictMono boundary_1}
  {boundary_zero_1 : boundary_1 0 = 0} {boundary_last_1 : boundary_1 (Fin.last cellCount_1) = T},
  { cellCount := cellCount, cellCount_pos := cellCount_pos, boundary := boundary,
        strictMono_boundary := strictMono_boundary, boundary_zero := boundary_zero, boundary_last := boundary_last } =
      { cellCount := cellCount_1, cellCount_pos := cellCount_pos_1, boundary := boundary_1,
        strictMono_boundary := strictMono_boundary_1, boundary_zero := boundary_zero_1,
        boundary_last := boundary_last_1 } →
    cellCount = cellCount_1 ∧ boundary ≍ boundary_1

RiffleLowerV2.wordCellCount.eq_1.type:
∀ {k N K : ℕ} (cuts : TimeProfile.Cuts k N K) (hN : 0 < N) (P : TimeProfile.BorelPartition k) {I : Finset (Fin K)}
  (x : RiffleLowerV2.WordOn k I) (i : Fin P.cellCount) (l : Fin k),
  RiffleLowerV2.wordCellCount cuts hN P x i l = {j : ↥I | P.classify (cuts.profile hN ↑j) = i ∧ x j = l}.card

TimeProfile.BorelPartition.mk.inj.type:
∀ {k cellCount : ℕ} {classify : TimeProfile.Simplex k → Fin cellCount} {measurable_classify : Measurable classify}
  {rep : Fin cellCount → TimeProfile.Simplex k} {classify_rep : ∀ (i : Fin cellCount), classify (rep i) = i}
  {cellCount_1 : ℕ} {classify_1 : TimeProfile.Simplex k → Fin cellCount_1}
  {measurable_classify_1 : Measurable classify_1} {rep_1 : Fin cellCount_1 → TimeProfile.Simplex k}
  {classify_rep_1 : ∀ (i : Fin cellCount_1), classify_1 (rep_1 i) = i},
  { cellCount := cellCount, classify := classify, measurable_classify := measurable_classify, rep := rep,
        classify_rep := classify_rep } =
      { cellCount := cellCount_1, classify := classify_1, measurable_classify := measurable_classify_1, rep := rep_1,
        classify_rep := classify_rep_1 } →
    cellCount = cellCount_1 ∧ classify ≍ classify_1 ∧ rep ≍ rep_1

RiffleLowerV2.Ascent.boundary_left_index.type:
∀ {N : ℕ} (G : RiffleLowerV2.PathEdges N),
  Set.InjOn (fun (e : Fin (N - 1)) => RiffleLowerV2.componentIndex G (RiffleLowerV2.edgeLeft e))
    {e : Fin (N - 1) | e ∉ G}

TimeProfile.Cuts.mk.inj.type:
∀ {k N K : ℕ} {count : Fin K → Fin k → ℕ} {sum_count : ∀ (j : Fin K), ∑ l : Fin k, count j l = N}
  {count_1 : Fin K → Fin k → ℕ} {sum_count_1 : ∀ (j : Fin K), ∑ l : Fin k, count_1 j l = N},
  { count := count, sum_count := sum_count } = { count := count_1, sum_count := sum_count_1 } → count = count_1

RiffleLowerV2.Ascent.successfulTranslate.type:
∀ {N : ℕ} (H0 : Finset ℤ) (G : RiffleLowerV2.PathEdges N) (r : ℝ),
  RiffleLowerV2.Ascent.successfulTranslates H0 G r =
    {q : Fin (N + 1) | r ≤ ↑(Finset.card (G ∩ RiffleLowerV2.internalEdges (RiffleLowerV2.clipTranslate N H0 ↑↑q)))}

RiffleLowerV2.ProfileTransfer.Compat.tim.type:
∀ (N K : ℕ) (a b : ℝ),
  RiffleLowerV2.ProfileTransfer.Compat.timePositions N K a b =
    {j : Fin K | a < TimeProfile.columnTime N j ∧ TimeProfile.columnTime N j ≤ b}

RiffleLowerV2.Thinning.Compat.intersecti.type:
∀ {α : Type u_1} [inst : DecidableEq α] (A : Finset α) {V : Finset α} {m : ℕ}
  (S : RiffleLowerV2.Thinning.Compat.Sample V m),
  (A ∩ ↑S).card ≤ (↑S).card → (↑S).card = m → ¬(A ∩ ↑S).card < m + 1 → False

RiffleLowerV2.Thinning.Compat.FiniteLaw..type:
∀ (Ω : Type u_4) [inst : Fintype Ω] [inst_1 : Nonempty Ω],
  RiffleLowerV2.Thinning.Compat.FiniteLaw.uniform Ω =
    { mass := fun (x : Ω) => 1 / ↑(Fintype.card Ω), mass_nonneg := ⋯, mass_sum := ⋯ }

_private.RiffleLowerV2.Thinning.Compat.H.type:
∀ (p : RiffleLowerV2.Thinning.Compat.HypergeomParams),
  RiffleLowerV2.Thinning.Compat.HypergeomParams.markedComplement✝ p =
    { population := p.population, marked := p.population - p.marked, draws := p.draws, marked_le := ⋯, draws_le := ⋯ }

RiffleLowerV2.Ascent.badRightBoundaries..type:
∀ {N : ℕ} (G : RiffleLowerV2.PathEdges N) (H : Finset (Fin N)),
  RiffleLowerV2.Ascent.badRightBoundaries G H =
    {e ∈ RiffleLowerV2.Ascent.retainedBoundaries G H | ¬RiffleLowerV2.Ascent.rightComponent G e ⊆ H}

RiffleLowerV2.RowPrescription.mk.inj.type:
∀ {N k K b : ℕ} {row : Fin b → Fin N} {word : Fin b → RiffleLowerV2.Word k K} {row_1 : Fin b → Fin N}
  {word_1 : Fin b → RiffleLowerV2.Word k K},
  { row := row, word := word } = { row := row_1, word := word_1 } → row = row_1 ∧ word = word_1

_private.RiffleLowerV2.Thinning.Compat.H.type:
∀ (p : RiffleLowerV2.Thinning.Compat.HypergeomParams),
  RiffleLowerV2.Thinning.Compat.HypergeomParams.swapped✝ p =
    { population := p.population, marked := p.draws, draws := p.marked, marked_le := ⋯, draws_le := ⋯ }
